{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_combined_inventory AS WITH store AS ( SELECT DATE::date AS date, LOT_MRP, PACKING, ITEM_MRP, LOT_CODE, ITEM_CF_1, ITEM_CF_2, ITEM_CF_3, ITEM_NAME, PACK_NAME as SIZE, STOCK_QTY, LOT_NUMBER, SHADE_NAME, BRANCH_CODE, BRANCH_NAME, GODOWN_CODE, GODOWN_NAME, LOT_SPRATE1, ADDLITEMCODE, CARTON_STOCK, TRY_TO_DATE(LOT_PUR_DATE, \'DD/MM/YYYY\') AS LOT_PUR_DATE, ADDLITEMCODE as SKU, LOT_SALE_RATE, ITEM_SALE_RATE, LOT_BASIC_RATE FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE::date = current_date() and (addlitemcode like \'4M%\' or addlitemcode like \'MP%\' or addlitemcode like \'4C%\' or addlitemcode like \'BP%\' or addlitemcode like \'SN%\' or addlitemcode like \'SH%\') ), virtual AS ( SELECT DATE::date AS date, LOT_MRP, PACKING, ITEM_MRP, LOT_CODE, ITEM_CF_1, ITEM_CF_2, ITEM_CF_3, ITEM_NAME, PACK_NAME as size, STOCK_QTY, LOT_NUMBER, SHADE_NAME, BRANCH_CODE, BRANCH_NAME, GODOWN_CODE, GODOWN_NAME, LOT_SPRATE1, ADDLITEMCODE, CARTON_STOCK, TRY_TO_DATE(LOT_PUR_DATE, \'DD/MM/YYYY\') AS LOT_PUR_DATE, ADDLITEMCODE as sku, LOT_SALE_RATE, ITEM_SALE_RATE, LOT_BASIC_RATE FROM snitch_db.maplemonk.logicerp_warehouse_get_stock_in_hand WHERE DATE::date = current_date() - 1 and item_name not like \'%CB%\' and lower(item_name) not like \'%uniform%\' and lower(item_name) not like \'%hanger%\' and lower(item_name) not like \'%shopping%\' ), warehouse_name AS ( SELECT DATE::date AS date, LOT_MRP, PACKING, ITEM_MRP, LOT_CODE, ITEM_CF_1, ITEM_CF_2, ITEM_CF_3, ITEM_NAME, PACK_NAME as size, STOCK_QTY, LOT_NUMBER, SHADE_NAME, BRANCH_CODE, BRANCH_NAME, GODOWN_CODE, GODOWN_NAME, LOT_SPRATE1, ADDLITEMCODE, CARTON_STOCK, TRY_TO_DATE(LOT_PUR_DATE, \'DD/MM/YYYY\') AS LOT_PUR_DATE, ADDLITEMCODE as sku, LOT_SALE_RATE, ITEM_SALE_RATE, LOT_BASIC_RATE FROM snitch_db.maplemonk.logic_virtual_b2b_ho_get_stock_in_hand WHERE DATE::date = current_date() and item_name not like \'%CB%\' and lower(item_name) not like \'%uniform%\' and lower(item_name) not like \'%hanger%\' and lower(item_name) not like \'%shopping%\' and (addlitemcode like \'4M%\' or addlitemcode like \'MP%\' or addlitemcode like \'4C%\' or addlitemcode like \'BP%\' or addlitemcode like \'SN%\' or addlitemcode like \'SH%\') ) (SELECT * FROM store UNION ALL SELECT * FROM warehouse_name UNION ALL SELECT * FROM virtual); create or replace table snitch_db.maplemonk.logic_final_inventory as with item as ( select distinct sku, skugroup, category_code from snitch_db.maplemonk.uc_final_item_master ), offline_store_mapping AS ( SELECT store_name, region, cluster, party FROM SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING ), final as( SELECT LEFT(a.sku, LENGTH(a.sku) - CHARINDEX(\'-\', REVERSE(a.sku))) AS sku_group, c.price, c.sku_class, c.status, a.*, CASE WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 0 AND 30 THEN \'0-30\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 31 AND 60 THEN \'30-60\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 61 AND 90 THEN \'60-90\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 91 AND 120 THEN \'90-120\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 121 AND 150 THEN \'120-150\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 151 AND 180 THEN \'150-180\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 181 AND 210 THEN \'180-210\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 211 AND 240 THEN \'210-240\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 241 AND 270 THEN \'240-270\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 271 AND 300 THEN \'270-300\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 301 AND 330 THEN \'300-330\' WHEN DATEDIFF(DAY, lot_pur_date, CURRENT_DATE) BETWEEN 331 AND 360 THEN \'330-360\' ELSE \'360+\' END as ageing_group, case when branch_name like \'%SNITCH - WH%\' then \'WAREHOUSE\' when branch_name like \'%COFO%\' or branch_name like \'%FOCO%\' or branch_name like \'%COCO%\' then \'STORE\' else \'UNKOWN\' END AS Location_Type, CASE WHEN GODOWN_NAME like \'%BAD%\' or godown_name like \'%DAMAGED%\' THEN \'BAD\' ELSE \'GOOD\' end as inventory_type, i.category_code as category, d.* FROM snitch_db.maplemonk.logic_combined_inventory a LEFT JOIN snitch_db.maplemonk.availability_master_v2 AS c ON UPPER(TRIM(LEFT(a.sku, LENGTH(a.sku) - CHARINDEX(\'-\', REVERSE(a.sku))))) = c.\"SKU_GROUP\" LEFT JOIN item as i ON UPPER(a.sku) = UPPER(i.sku) LEFT JOIN offline_store_mapping as d on branch_name = d.store_name) select * from final; CREATE OR REPLACE TABLE snitch_db.maplemonk.final_inventory AS WITH am AS ( SELECT DISTINCT sku_group, sku_class FROM snitch_db.maplemonk.availability_master_v2 ), item AS ( SELECT DISTINCT skugroup, category_code FROM snitch_db.maplemonk.uc_final_item_master ), UC_final AS ( SELECT CASE WHEN a.facility = \'SAPL_EMIZA\' THEN \'SNITCH - WH - EMIZA\' WHEN a.facility = \'SAPL-WH2\' THEN \'SNITCH - WH - YELHANKA 2\' WHEN a.facility = \'SAPL-WH1\' THEN \'SNITCH - WH - YELHANKA\' WHEN a.facility = \'JAYANAGAR_EBO\' THEN \'SNITCH - WH - JAYANAGAR\' WHEN a.facility = \'SAPL-NORTH-TAURU\' THEN \'SNITCH - WH - NORTH\' ELSE \'NA\' END AS facility, CAST(COALESCE(NULLIF(a.inventory, \'\'), 0) AS INTEGER) AS inventory, CAST(COALESCE(NULLIF(a.\"Inventory Blocked\", \'\'), 0) AS INTEGER) AS InventoryBlocked, CAST(COALESCE(NULLIF(a.\"Inventory Not Synced\", \'\'), 0) AS INTEGER) AS InventoryNotSynced, CAST(COALESCE(NULLIF(a.\"Bad Inventory\", \'\'), 0) AS INTEGER) AS BadInventory, CAST(COALESCE(NULLIF(a.\"Not Found\", \'\'), 0) AS INTEGER) AS NotFound, CAST(COALESCE(NULLIF(a.\"Putaway Pending\", \'\'), 0) AS INTEGER) AS PutawayPending, CAST(COALESCE(NULLIF(a.\"Putback Pending\", \'\'), 0) AS INTEGER) AS PutbackPending, CAST(COALESCE(NULLIF(a.\"Stock In Transfer\", \'\'), 0) AS INTEGER) AS StockInTransfer, ( CAST(COALESCE(NULLIF(a.inventory, \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Inventory Blocked\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Inventory Not Synced\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Bad Inventory\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Not Found\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Putaway Pending\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Putback Pending\", \'\'), 0) AS INTEGER) + CAST(COALESCE(NULLIF(a.\"Stock In Transfer\", \'\'), 0) AS INTEGER) ) AS TotalInventory, a.\"Item SkuCode\" AS sku, c.sku_class, c.sku_group, i.category_code AS category FROM snitch_db.maplemonk.snitch_final_inventory_wh2 AS a LEFT JOIN am AS c ON UPPER(TRIM(LEFT(a.\"Item SkuCode\", LENGTH(a.\"Item SkuCode\") - CHARINDEX(\'-\', REVERSE(a.\"Item SkuCode\"))))) = c.sku_group LEFT JOIN item AS i ON c.sku_group = i.skugroup WHERE a.facility IN (\'SAPL-WH1\', \'SAPL-WH2\', \'SAPL_EMIZA\',\'JAYANAGAR_EBO\',\'SAPL-NORTH-TAURU\') and a.date = current_date ), logic_final AS ( SELECT branch_name AS facility, CASE WHEN GODOWN_NAME NOT LIKE \'%BAD%\' AND GODOWN_NAME NOT LIKE \'%DAMAGED%\' THEN SUM(stock_qty) ELSE NULL END AS good_inv, NULL AS invblocked, NULL AS notsynced, CASE WHEN GODOWN_NAME LIKE \'%BAD%\' OR GODOWN_NAME LIKE \'%DAMAGED%\' THEN SUM(stock_qty) ELSE NULL END AS bad_inv, NULL AS notfound, NULL AS putawaypending, NULL AS putbackpending, NULL AS stockin, SUM(stock_qty) AS total_inventory, ADDLITEMCODE AS SKU, c.sku_class, c.sku_group, i.category_code AS category FROM snitch_db.maplemonk.logicerp_warehouse_get_stock_in_hand LEFT JOIN am AS c ON UPPER(TRIM(LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))))) = c.sku_group LEFT JOIN item AS i ON c.sku_group = i.skugroup WHERE DATE::DATE = CURRENT_DATE -1 and item_name not like \'%CB%\' and lower(item_name) not like \'%uniform%\' and lower(item_name) not like \'%hanger%\' and lower(item_name) not like \'%shopping%\' and (addlitemcode like \'4M%\' or addlitemcode like \'MP%\' or addlitemcode like \'4C%\' or addlitemcode like \'BP%\' or addlitemcode like \'SN%\' or addlitemcode like \'SH%\') GROUP BY branch_name, ADDLITEMCODE, GODOWN_NAME, c.sku_class, c.sku_group, i.category_code ) SELECT \'UC\' as SOURCE ,* FROM UC_final UNION ALL SELECT \'LOGIC\' as SOURCE, * FROM logic_final;",
                    "transaction": true
                }
            ) }}
